{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}
    edges = []
    for u, v, d in distances:
        du = core_dist[u]
        dv = core_dist[v]
        w = max(du, dv, d)
        # canonicalize endpoints: ensure u < v lexicographically
        if u > v:
            u, v = v, u
        edges.append((u, v, w))
    # sort by weight, then by first endpoint, then by second endpoint
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == n - 1:
                break
    if len(mst) != n - 1:
        raise ValueError('Graph is disconnected, cannot form MST')
    return {'mst_edges': mst, 'total_weight': total}"
}
